import { test, expect, type APIRequestContext } from '@playwright/test';

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status(), 'send-code 应返回 200').toBe(200);
  const sendJson = await sendRes.json();
  expect(sendJson.devCode).toMatch(/^\d{6}$/);

  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status(), 'verify-code 应返回 200').toBe(200);
  const verifyJson = await verifyRes.json();
  expect(verifyJson.ok).toBe(true);
  return verifyJson.user;
}

test.describe.serial('动态改版（X.com列表流、点击/收藏/分享直达、右侧导航、多账号切换）加固盲测套件', () => {
  test('1. 主页单列列表形态、点击统计并发累加、收藏隐私隔离、分享 URL 直达与删帖级联清理', async ({ page, browser }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const ctxB = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      const userA = await loginUser(page.request, makeEmail('feed-a'), '列表作者A');
      await loginUser(ctxB.request, makeEmail('feed-b'), '旁观读者B');

      // 异常与权限边界校验
      expect((await anonCtx.request.post('/api/posts/non-existent-id/view')).status()).toBe(404);
      expect((await anonCtx.request.post('/api/posts/non-existent-id/share')).status()).toBe(404);
      expect((await anonCtx.request.post('/api/posts/non-existent-id/bookmark')).status()).toBe(401);
      expect((await page.request.post('/api/posts/non-existent-id/bookmark')).status()).toBe(404);
      expect((await anonCtx.request.get(`/api/users/${userA.id}/activity?tab=bookmarks`)).status()).toBe(401);

      const tag = `动态改版${Date.now().toString().slice(-4)}`;
      const title1 = `X风格单列动态一-${Date.now()}`;
      const content1 = '第一条正文内容，用于校验列表流展示、点击、收藏与分享直达。';
      const title2 = `X风格单列动态二-${Date.now()}`;

      const p1Res = await page.request.post('/api/posts', {
        data: { title: title1, content: content1, tags: [tag] },
      });
      expect(p1Res.status()).toBe(201);
      const postId = (await p1Res.json()).post.id as string;

      const p2Res = await page.request.post('/api/posts', {
        data: { title: title2, content: '第二条动态用于验证纵向单列排列', tags: [tag] },
      });
      expect(p2Res.status()).toBe(201);

      // 并发点击累加校验（匿名访客也可正常累加）
      const concurrentViews = await Promise.all([
        anonCtx.request.post(`/api/posts/${postId}/view`),
        anonCtx.request.post(`/api/posts/${postId}/view`),
        page.request.post(`/api/posts/${postId}/view`),
      ]);
      for (const r of concurrentViews) {
        expect(r.status()).toBe(200);
      }
      const afterViewsJson = await (await page.request.get(`/api/posts/${postId}`)).json();
      expect(afterViewsJson.post.viewsCount, '3次并发点击后 viewsCount 应至少为 3').toBeGreaterThanOrEqual(3);

      // 进入首页验证：无 /admin 链接泄露 + 单列纵向列表几何形态
      await page.goto('/');
      await expect(page.locator('a[href="/admin"]')).toHaveCount(0);
      await expect(page.locator('a[href="/admin/"]')).toHaveCount(0);

      const card1 = page.locator('article').filter({ hasText: title1 }).first();
      const card2 = page.locator('article').filter({ hasText: title2 }).first();
      await expect(card1).toBeVisible({ timeout: 10000 });
      await expect(card2).toBeVisible({ timeout: 10000 });

      const box1 = await card1.boundingBox();
      const box2 = await card2.boundingBox();
      expect(box1, '动态卡片一应具备可见尺寸').not.toBeNull();
      expect(box2, '动态卡片二应具备可见尺寸').not.toBeNull();
      if (box1 && box2) {
        expect(Math.abs(box1.x - box2.x), '列表流中两条动态左边界应对齐而非多列瀑布流').toBeLessThanOrEqual(24);
        const topBox = box1.y < box2.y ? box1 : box2;
        const bottomBox = box1.y < box2.y ? box2 : box1;
        expect(bottomBox.y, '动态卡片应纵向依次排布不横向并列').toBeGreaterThanOrEqual(topBox.y + topBox.height - 12);
      }

      // UI 点击收藏按钮并验证状态与计数持久化
      const bookmarkBtn = card1.getByRole('button', { name: /收藏/i }).first();
      await expect(bookmarkBtn).toBeVisible();
      const bookmarkPromise = page.waitForResponse(
        (res) => res.url().includes(`/api/posts/${postId}/bookmark`) && res.request().method() === 'POST'
      );
      await bookmarkBtn.click();
      const bookmarkRes = await bookmarkPromise;
      expect(bookmarkRes.status()).toBe(200);
      const bookmarkJson = await bookmarkRes.json();
      expect(bookmarkJson.bookmarked).toBe(true);
      expect(bookmarkJson.bookmarksCount).toBe(1);

      // 收藏隐私隔离（IDOR 防护）：用户 B 严禁查看用户 A 的收藏列表
      const crossBookmarks = await ctxB.request.get(`/api/users/${userA.id}/activity?tab=bookmarks`);
      expect(crossBookmarks.status(), '他人跨用户查询收藏列表必须返回 403').toBe(403);

      // 用户 A 个人主页「收藏」标签页可查看该动态
      const ownBookmarksJson = await (await page.request.get(`/api/users/${userA.id}/activity?tab=bookmarks`)).json();
      expect(ownBookmarksJson.items.some((p: { id: string }) => p.id === postId)).toBe(true);

      // UI 点击分享按钮，校验分享接口与直达路径
      const shareBtn = card1.getByRole('button', { name: /分享/i }).first();
      await expect(shareBtn).toBeVisible();
      const sharePromise = page.waitForResponse(
        (res) => res.url().includes(`/api/posts/${postId}/share`) && res.request().method() === 'POST'
      );
      await shareBtn.click();
      const shareRes = await sharePromise;
      expect(shareRes.status()).toBe(200);
      const shareJson = await shareRes.json();
      expect(shareJson.sharesCount).toBeGreaterThanOrEqual(1);
      expect(shareJson.sharePath).toBe(`/posts/${postId}`);

      // 匿名访客通过分享 URL /posts/:id 直接跳转并展示动态详情，同时点击数继续递增
      const viewsBeforeShareJump = afterViewsJson.post.viewsCount as number;
      const anonPage = await anonCtx.newPage();
      const anonErrors: string[] = [];
      anonPage.on('pageerror', (err) => anonErrors.push(err.message));
      await anonPage.setViewportSize({ width: 1280, height: 800 });
      await anonPage.goto(`/posts/${postId}`);
      await expect(anonPage.getByText(title1).first()).toBeVisible({ timeout: 10000 });
      await expect(anonPage.getByText(content1).first()).toBeVisible({ timeout: 10000 });
      await expect
        .poll(async () => (await (await page.request.get(`/api/posts/${postId}`)).json()).post.viewsCount)
        .toBeGreaterThan(viewsBeforeShareJump);

      // 访问不存在的分享 URL 应优雅展示错误提示且无 JS 崩溃
      await anonPage.goto('/posts/non-existent-share-id');
      await expect(anonPage.getByText(/不存在|无法加载|未找到|已删除/i).first()).toBeVisible({ timeout: 10000 });
      expect(anonErrors, '直达有效及无效分享链接均不应触发前端异常').toEqual([]);
      await anonPage.close();

      // 进入个人主页 UI 核对「收藏」标签页展示
      const sidebar = page.locator('aside').first();
      await sidebar
        .getByRole('button', { name: /主页/ })
        .or(sidebar.getByRole('link', { name: /主页/ }))
        .first()
        .click();
      const bookmarksTab = page
        .getByRole('tab', { name: /收藏/ })
        .or(page.getByRole('button', { name: /收藏/ }))
        .first();
      await expect(bookmarksTab).toBeVisible({ timeout: 10000 });
      await bookmarksTab.click();
      await expect(page.getByText(title1).first()).toBeVisible({ timeout: 10000 });

      // 删帖级联清理：删除后收藏列表不再残留且详情返回 404
      expect((await page.request.delete(`/api/posts/${postId}`)).status()).toBe(200);
      expect((await page.request.get(`/api/posts/${postId}`)).status()).toBe(404);
      const bookmarksAfterDel = await (await page.request.get(`/api/users/${userA.id}/activity?tab=bookmarks`)).json();
      expect(bookmarksAfterDel.items.some((p: { id: string }) => p.id === postId)).toBe(false);
      expect(pageErrors).toEqual([]);
    } finally {
      await ctxB.close();
      await anonCtx.close();
    }
  });

  test('2. 右侧导航（热门话题、推荐关注）接口契约、隐私脱敏、三栏几何布局与交互闭环', async ({ page, browser }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const ctxCreator = await browser.newContext();
    try {
      const creatorEmail = makeEmail('discover-creator');
      const creatorNick = `活跃达人${Date.now().toString().slice(-4)}`;
      const creator = await loginUser(ctxCreator.request, creatorEmail, creatorNick);

      const hotTag = `趋势热词${Date.now().toString().slice(-4)}`;
      const otherTag = `普通标签${Date.now().toString().slice(-4)}`;
      const hotPostTitle = `热词精选帖子-${Date.now()}`;
      const otherPostTitle = `其他分类帖子-${Date.now()}`;

      // 发布多篇带热词标签的动态提升其热度排名
      for (let i = 0; i < 3; i += 1) {
        const res = await ctxCreator.request.post('/api/posts', {
          data: {
            title: i === 0 ? hotPostTitle : `${hotPostTitle}-${i}`,
            content: '测试热门话题实时聚合排序', 
            tags: [hotTag],
          },
        });
        expect(res.status()).toBe(201);
      }
      await ctxCreator.request.post('/api/posts', {
        data: { title: otherPostTitle, content: '用于验证点击热门话题筛选隔离', tags: [otherTag] },
      });

      const viewer = await loginUser(page.request, makeEmail('discover-viewer'), '探索用户');

      // 发现接口参数边界与隐私脱敏审计
      expect((await page.request.get('/api/discover/topics?limit=0')).status()).toBe(400);
      expect((await page.request.get('/api/discover/topics?limit=99')).status()).toBe(400);
      expect((await page.request.get('/api/discover/recommended-users?limit=0')).status()).toBe(400);
      expect((await page.request.get('/api/discover/recommended-users?limit=99')).status()).toBe(400);

      const topicsJson = await (await page.request.get('/api/discover/topics?limit=10')).json();
      expect(Array.isArray(topicsJson.topics)).toBe(true);
      expect(topicsJson.topics.some((t: { tag: string }) => t.tag === hotTag)).toBe(true);

      const recRes = await page.request.get('/api/discover/recommended-users?limit=10');
      expect(recRes.status()).toBe(200);
      const recRawText = await recRes.text();
      expect(recRawText, '推荐关注接口严禁泄露任何用户邮箱').not.toContain(creatorEmail);
      const recJson = JSON.parse(recRawText);
      expect(recJson.users.some((u: { id: string }) => u.id === viewer.id), '推荐关注不应包含当前登录用户本人').toBe(false);
      expect(recJson.users.some((u: { id: string }) => u.id === creator.id)).toBe(true);

      // 浏览器 1440px 宽屏验证三栏几何布局：左导航 < 居中列表 < 右侧发现栏
      await page.goto('/');
      const leftSidebar = page.locator('aside').first();
      const feedArticle = page.locator('article').filter({ hasText: hotPostTitle }).first();
      const trendingTitle = page.getByText(/热门话题/).first();
      const recTitle = page.getByText(/推荐关注/).first();

      await expect(leftSidebar).toBeVisible({ timeout: 10000 });
      await expect(feedArticle).toBeVisible({ timeout: 10000 });
      await expect(trendingTitle).toBeVisible({ timeout: 10000 });
      await expect(recTitle).toBeVisible({ timeout: 10000 });

      const leftBox = await leftSidebar.boundingBox();
      const articleBox = await feedArticle.boundingBox();
      const trendingBox = await trendingTitle.boundingBox();
      expect(leftBox && articleBox && trendingBox).toBeTruthy();
      if (leftBox && articleBox && trendingBox) {
        expect(leftBox.x + leftBox.width, '左侧导航栏应位于动态列表左侧').toBeLessThanOrEqual(articleBox.x + 24);
        expect(trendingBox.x, '右侧热门话题模块应位于动态列表右侧').toBeGreaterThanOrEqual(
          articleBox.x + articleBox.width - 20
        );
      }

      // 点击右侧热门话题筛选动态流
      const rightAside = page.locator('aside').nth(1);
      const topicBtn = rightAside
        .getByRole('button', { name: new RegExp(hotTag) })
        .or(page.getByRole('button', { name: new RegExp(hotTag) }))
        .first();
      await expect(topicBtn).toBeVisible({ timeout: 10000 });
      await topicBtn.click();
      await expect(page.locator('article').filter({ hasText: hotPostTitle }).first()).toBeVisible({ timeout: 10000 });
      await expect(page.locator('article').filter({ hasText: otherPostTitle })).toHaveCount(0, { timeout: 10000 });

      // 在右侧推荐关注模块直接点击关注目标博主
      const recUserRow = rightAside
        .locator('li, div')
        .filter({ hasText: creatorNick })
        .filter({ has: page.getByRole('button', { name: /^关注$/ }) })
        .last();
      const followBtn = recUserRow
        .getByRole('button', { name: /^关注$/ })
        .or(rightAside.getByRole('button', { name: /^关注$/ }))
        .first();
      await expect(followBtn).toBeVisible({ timeout: 10000 });
      const followResp = page.waitForResponse(
        (r) => r.url().includes('/follow') && r.request().method() === 'POST'
      );
      await followBtn.click();
      expect((await followResp).status()).toBe(200);
      await expect(rightAside.getByRole('button', { name: /已关注/ }).first()).toBeVisible({ timeout: 10000 });
      expect(pageErrors).toEqual([]);
    } finally {
      await ctxCreator.close();
    }
  });

  test('3. 多账号安全切换、防越权接管、UI 身份状态同步、添加账号与分级退出闭环', async ({ page, browser }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const ctxOther = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      // 未登录切换账号必须返回 401
      expect((await anonCtx.request.post('/api/auth/switch', { data: { userId: 'any-id' } })).status()).toBe(401);

      // 独立浏览器上下文中的第三方账号 C（从未在 page 上下文登录）
      const userC = await loginUser(ctxOther.request, makeEmail('multi-victim-c'), '外部账号C');

      const nickA = `多账号甲${Date.now().toString().slice(-4)}`;
      const nickB = `多账号乙${Date.now().toString().slice(-4)}`;
      const userA = await loginUser(page.request, makeEmail('multi-a'), nickA);

      // 账号 A 发布并收藏一篇动态，用于验证切换账号后前端收藏态同步
      const sharedTitle = `身份态同步验证帖-${Date.now()}`;
      const postId = (
        await (
          await page.request.post('/api/posts', {
            data: { title: sharedTitle, content: '仅账号A收藏，切换至账号B应显示未收藏' },
          })
        ).json()
      ).post.id as string;
      expect((await page.request.post(`/api/posts/${postId}/bookmark`)).status()).toBe(200);

      // 在同一浏览器上下文登录第二个账号 B
      const userB = await loginUser(page.request, makeEmail('multi-b'), nickB);

      // 参数边界与安全隔离（防跨用户越权接管）：空 userId 返回 400，未托管的外部账号 C 返回 403
      expect((await page.request.post('/api/auth/switch', { data: { userId: '' } })).status()).toBe(400);
      expect(
        (await page.request.post('/api/auth/switch', { data: { userId: userC.id } })).status(),
        '严禁切换至未在当前浏览器验证过的外部账号'
      ).toBe(403);

      const accListJson = await (await page.request.get('/api/auth/accounts')).json();
      expect(accListJson.activeUserId).toBe(userB.id);
      expect(accListJson.accounts.some((a: { id: string }) => a.id === userA.id)).toBe(true);
      expect(accListJson.accounts.some((a: { id: string }) => a.id === userB.id)).toBe(true);

      // 账号 B 视角下该动态未收藏
      const postAsB = await (await page.request.get(`/api/posts/${postId}`)).json();
      expect(postAsB.post.bookmarkedByMe).toBe(false);

      // 浏览器 UI 验证：当前为账号 B，打开左下角账号菜单一键切换至账号 A
      await page.goto('/');
      const sidebar = page.locator('aside').first();
      const triggerB = sidebar
        .getByRole('button', { name: new RegExp(`${nickB}|个人资料|账号`, 'i') })
        .last();
      await expect(triggerB).toBeVisible({ timeout: 10000 });
      await triggerB.click();

      const switchToA = page
        .getByRole('menuitem', { name: new RegExp(nickA) })
        .or(page.getByRole('button', { name: new RegExp(nickA) }))
        .first();
      await expect(switchToA).toBeVisible({ timeout: 10000 });

      const switchPromise = page.waitForResponse(
        (r) => r.url().includes('/api/auth/switch') && r.request().method() === 'POST'
      );
      await switchToA.click();
      expect((await switchPromise).status()).toBe(200);

      // 验证激活身份已变为账号 A，且接口与页面数据均已同步为 A 视角
      const meAsA = await (await page.request.get('/api/auth/me')).json();
      expect(meAsA.user.id).toBe(userA.id);
      const postAsA = await (await page.request.get(`/api/posts/${postId}`)).json();
      expect(postAsA.post.bookmarkedByMe).toBe(true);
      await expect(sidebar.getByText(nickA).first()).toBeVisible({ timeout: 10000 });

      // 通过左下角账号菜单「添加其他账号」UI 流程再新增第三个账号 D
      const triggerA = sidebar
        .getByRole('button', { name: new RegExp(`${nickA}|个人资料|账号`, 'i') })
        .last();
      await triggerA.click();
      const addAccountBtn = page
        .getByRole('menuitem', { name: /添加.*账号/i })
        .or(page.getByRole('button', { name: /添加.*账号/i }))
        .first();
      await expect(addAccountBtn).toBeVisible({ timeout: 10000 });
      await addAccountBtn.click();

      const emailD = makeEmail('multi-d');
      const nickD = `新加丙${Date.now().toString().slice(-4)}`;
      const emailInput = page
        .getByPlaceholder(/邮箱|email/i)
        .or(page.locator('input[type="email"]'))
        .first();
      await expect(emailInput).toBeVisible({ timeout: 10000 });
      await emailInput.fill(emailD);

      const sendDPromise = page.waitForResponse(
        (r) => r.url().includes('/api/auth/send-code') && r.request().method() === 'POST'
      );
      await page.getByRole('button', { name: /获取验证码|发送验证码/i }).first().click();
      const sendDJson = await (await sendDPromise).json();
      expect(sendDJson.devCode).toMatch(/^\d{6}$/);

      await page
        .getByPlaceholder(/验证码|code/i)
        .or(page.locator('input[inputmode="numeric"]'))
        .first()
        .fill(sendDJson.devCode);
      const nickInput = page.getByPlaceholder(/昵称/i).first();
      if (await nickInput.isVisible().catch(() => false)) {
        await nickInput.fill(nickD);
      }
      const verifyDPromise = page.waitForResponse(
        (r) => r.url().includes('/api/auth/verify-code') && r.request().method() === 'POST'
      );
      await page
        .getByRole('button', { name: /验证并登录|确认登录|登录/i })
        .filter({ hasNotText: /获取验证码|发送验证码/i })
        .first()
        .click();
      expect((await verifyDPromise).status()).toBe(200);

      const meAsD = await (await page.request.get('/api/auth/me')).json();
      expect(meAsD.user.email).toBe(emailD);
      const userDId = meAsD.user.id as string;

      // 退出当前账号 D -> 自动切回剩余账号，且严禁再次切回已注销的账号 D
      const logoutOneRes = await page.request.post('/api/auth/logout', { data: {} });
      expect(logoutOneRes.status()).toBe(200);
      const meAfterOne = await (await page.request.get('/api/auth/me')).json();
      expect(meAfterOne.authenticated).toBe(true);
      expect(meAfterOne.user.id).not.toBe(userDId);

      const switchRevokedRes = await page.request.post('/api/auth/switch', { data: { userId: userDId } });
      expect(switchRevokedRes.status(), '已退出注销的账号严禁再次切回').toBe(403);

      // 一键退出全部账号 -> 所有托管账号清空，恢复未登录态
      const logoutAllRes = await page.request.post('/api/auth/logout', { data: { all: true } });
      expect(logoutAllRes.status()).toBe(200);
      const meAfterAll = await (await page.request.get('/api/auth/me')).json();
      expect(meAfterAll.authenticated).toBe(false);
      const accAfterAll = await (await page.request.get('/api/auth/accounts')).json();
      expect(accAfterAll.accounts).toEqual([]);
      expect(pageErrors).toEqual([]);
    } finally {
      await ctxOther.close();
      await anonCtx.close();
    }
  });
});
